#include "study_support.h"
#include "../rushlarsen-cuda/utils.h"
int main(int argc,char**argv){try{if(argc!=2)return 2;std::string root=argv[1];auto cs=rlcases(root,false);std::ofstream o(root+"/oracle_compact.bin",std::ios::binary);unsigned nc=cs.size();o.write((char*)&nc,4);for(auto&c:cs){o.write((char*)&c.np,4);auto v=c.s;forward_rush_larsen(v.data(),c.t,c.dt,c.p.data(),c.np);for(double x:v)if(!std::isfinite(x))throw std::runtime_error("nonfinitefirstCPU");o.write((char*)v.data(),v.size()*8);v=c.s;double t=c.t;for(unsigned s=0;s<c.steps;s++){forward_rush_larsen(v.data(),t,c.dt,c.p.data(),c.np);t+=c.dt;}for(double x:v)if(!std::isfinite(x))throw std::runtime_error("nonfinitefinalCPU");o.write((char*)v.data(),v.size()*8);}return !o;}catch(std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
